/* Native HIT analysis from the user-supplied four-page Astro Vastu document. */
(()=>{'use strict';const RULES=[{angle:30,orb:3,kind:'positive',effect:'Feel-good factor'},{angle:60,orb:5,kind:'positive',effect:'Full support'},{angle:120,orb:8,kind:'positive',effect:'Strong relationship'},{angle:45,orb:3,kind:'negative',effect:'Uncomfortable influence'},{angle:90,orb:5,kind:'negative',effect:'Disturbance / hindrance'},{angle:180,orb:8,kind:'negative',effect:'Strong opposition'}],LORDS=['Ma','Ve','Me','Mo','Su','Me','Ve','Ma','Ju','Sa','Sa','Ju'],DIR=[['East / east-southeast','E4 E5 E6'],['Northwest / west-northwest','W6 W7 W8 N1'],['North-northwest','N2 N3'],['North-northeast','N6 N7'],['East-northeast','E2 E3'],['North','N4 N5'],['West-southwest / southwest','S8 W1 W2 W3'],['South-southwest','S6 S7'],['Northeast','N8 E1'],['South / south-southeast','S2 S3 S4 S5'],['West','W4 W5'],['Southeast / east-southeast','E7 E8 S1']];
const CORRESPONDENCES={Su:{deity:'Rama',avatar:'Rama',herb:'Lakh Dana / Anant Mool',items:['Copper decoration','Sun or lion picture','Rama picture']},Mo:{deity:'Shiva',avatar:'Krishna',herb:'Rai',items:['Water decoration','Silver ornament','Shiva picture','White decoration']},Ma:{deity:'Hanuman',avatar:'Narasimha',herb:'Maal Kangani',items:['Red decoration','Hanuman picture']},Me:{deity:'Vishnu',avatar:'Buddha',herb:'Amba Haladi',items:['Green decoration','Books / stationery','Bird picture','Vishnu picture']},Ju:{deity:'Brahma',avatar:'Vamana',herb:'Nagarmotha',items:['Religious books','Brass ornament','Yellow / golden decoration','Brahma picture']},Ve:{deity:'Lakshmi',avatar:'Parashurama',herb:'Kalonji',items:['Decorative items','Jewellery','Flower picture','Lakshmi picture']},Sa:{deity:'Bhairav',avatar:'Kurma',herb:'Datura root',items:['Black decoration','Iron ornament','Bhairav picture']},Ra:{deity:'Durga',avatar:'Varaha',herb:'Paneer Dodi',items:['Blue / brown decoration','Elephant picture']},Ke:{deity:'Ganesh',avatar:'Matsya',herb:'Banana root',items:['Multicolour decoration','Black-and-white decoration','Dog picture','Ganesh picture']}};
const mod=x=>((x%360)+360)%360,sign=x=>Math.floor(mod(x)/30),separation=(a,b)=>Math.abs(mod(a-b+180)-180);
function aspect(a,b){if(!Number.isFinite(a)||!Number.isFinite(b))return null;const distance=separation(a,b),rule=RULES.find(r=>Math.abs(distance-r.angle)<=r.orb+1e-9);return rule?{...rule,distance,offset:Math.abs(distance-rule.angle)}:null;}
function direction(longitude){const index=sign(longitude);return {sign:index,text:DIR[index][0],zones:DIR[index][1]};}
function analyze(model,periods,{level='all',type='all',kind='all',stars=true}={}){if(!model?.ready||!periods?.ready)return {ready:false,reason:periods?.reason||'Calculate the native kundali first.',hits:[],remedies:[]};const planets=new Map(model.planets.map(p=>[p.id,p])),roles=new Map();for(const p of periods.periods){if(level!=='all'&&p.level!==level)continue;const id=p.id||p.lord,point=planets.get(id);if(!point)continue;if(!roles.has(id))roles.set(id,[]);roles.get(id).push(p.level);if(stars&&planets.has(point.stl)){if(!roles.has(point.stl))roles.set(point.stl,[]);roles.get(point.stl).push(p.level+' star');}}
const hits=[];function add(mode,from,to,target,house=null){if(!from||!to)return;const match=aspect(from.longitude/3600,to.longitude/3600);if(!match||kind!=='all'&&match.kind!==kind)return;hits.push({type:mode,from:from.id,target,house,active:mode==='planet'?to.id:from.id,roles:roles.get(mode==='planet'?to.id:from.id),starPriority:roles.get(mode==='planet'?to.id:from.id).some(r=>r.endsWith('star')),...match,fromDirection:direction(from.longitude/3600),targetDirection:direction(to.longitude/3600),fromLongitude:from.longitude/3600,targetLongitude:to.longitude/3600});}
for(const [id] of roles){const active=planets.get(id);if(type==='all'||type==='planet')for(const p of planets.values())if(p.id!==id)add('planet',p,active,id);if(type==='all'||type==='house')for(const cusp of model.houses)add('house',active,cusp,'Cusp '+cusp.id,cusp.id);if(type==='all'||type==='lord')for(const cusp of model.houses){const owner=LORDS[cusp.signIndex];if(owner!==id)add('lord',active,planets.get(owner),owner,cusp.id);}}
hits.sort((a,b)=>Number(b.starPriority)-Number(a.starPriority)||a.kind.localeCompare(b.kind)||a.offset-b.offset);const remedies=[],keys=new Set();for(const hit of hits.filter(h=>h.kind==='negative')){const itemId=hit.type==='planet'?hit.from:hit.active,key=itemId+'|'+hit.fromDirection.sign+'|'+hit.targetDirection.sign;if(keys.has(key))continue;keys.add(key);remedies.push({planet:itemId,fromDirection:hit.fromDirection,targetDirection:hit.targetDirection,...CORRESPONDENCES[itemId],positiveDirections:[...new Map([30,60,120].flatMap(a=>[direction(hit.targetLongitude+a),direction(hit.targetLongitude-a)]).map(d=>[d.sign,d])).values()]});}
return {ready:true,level,type,kind,stars,periods:periods.periods,roles:[...roles].map(([id,roles])=>({id,roles})),hits,remedies};}
globalThis.KPHitMath=Object.freeze({RULES,DIR,CORRESPONDENCES,aspect,direction,analyze});})();
